// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetHealth Process health check
	// (GET /healthz)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// GetReadiness Dependency readiness check
	// (GET /readyz)
	GetReadiness(ctx context.Context, request GetReadinessRequestObject) (GetReadinessResponseObject, error)
	// IssueAIJobCapability Issue an App Attest-bound one-time background job capability
	// (POST /v1/ai/job-capabilities)
	IssueAIJobCapability(ctx context.Context, request IssueAIJobCapabilityRequestObject) (IssueAIJobCapabilityResponseObject, error)
	// EnqueueAIJob Enqueue a background managed-AI job
	// (POST /v1/ai/jobs)
	EnqueueAIJob(ctx context.Context, request EnqueueAIJobRequestObject) (EnqueueAIJobResponseObject, error)
	// CancelAIJob Cancel a queued or running background job
	// (DELETE /v1/ai/jobs/{id})
	CancelAIJob(ctx context.Context, request CancelAIJobRequestObject) (CancelAIJobResponseObject, error)
	// GetAIJob Read a background job
	// (GET /v1/ai/jobs/{id})
	GetAIJob(ctx context.Context, request GetAIJobRequestObject) (GetAIJobResponseObject, error)
	// GetAIQuota Read the current AI and free-recognition quota snapshot
	// (GET /v1/ai/quota)
	GetAIQuota(ctx context.Context, request GetAIQuotaRequestObject) (GetAIQuotaResponseObject, error)
	// CancelRecognitionSession Release an unfinished free meal-recognition reservation
	// (DELETE /v1/ai/recognition-sessions/{id})
	CancelRecognitionSession(ctx context.Context, request CancelRecognitionSessionRequestObject) (CancelRecognitionSessionResponseObject, error)
	// CompleteRecognitionSession Commit one successfully saved free meal-recognition session
	// (POST /v1/ai/recognition-sessions/{id}/complete)
	CompleteRecognitionSession(ctx context.Context, request CompleteRecognitionSessionRequestObject) (CompleteRecognitionSessionResponseObject, error)
	// CompleteAIRequest Complete a constrained managed-AI request
	// (POST /v1/ai/requests)
	CompleteAIRequest(ctx context.Context, request CompleteAIRequestRequestObject) (CompleteAIRequestResponseObject, error)
	// StreamAIRequest Stream a constrained managed-AI request as server-sent events
	// (POST /v1/ai/streams)
	StreamAIRequest(ctx context.Context, request StreamAIRequestRequestObject) (StreamAIRequestResponseObject, error)
	// ProcessAppStoreNotification Receive an App Store Server Notification V2
	// (POST /v1/app-store/notifications)
	ProcessAppStoreNotification(ctx context.Context, request ProcessAppStoreNotificationRequestObject) (ProcessAppStoreNotificationResponseObject, error)
	// IssueAttestationChallenge Issue a one-time App Attest challenge
	// (POST /v1/attest/challenges)
	IssueAttestationChallenge(ctx context.Context, request IssueAttestationChallengeRequestObject) (IssueAttestationChallengeResponseObject, error)
	// RegisterAttestationKey Register an App Attest key
	// (POST /v1/attest/keys)
	RegisterAttestationKey(ctx context.Context, request RegisterAttestationKeyRequestObject) (RegisterAttestationKeyResponseObject, error)
	// ActivateDevelopmentEntitlement Activate a development-only managed entitlement
	// (POST /v1/dev/entitlements/activate)
	ActivateDevelopmentEntitlement(ctx context.Context, request ActivateDevelopmentEntitlementRequestObject) (ActivateDevelopmentEntitlementResponseObject, error)
	// SynchronizeSubscriptionTransaction Synchronize a locally verified StoreKit transaction
	// (POST /v1/entitlements/transactions)
	SynchronizeSubscriptionTransaction(ctx context.Context, request SynchronizeSubscriptionTransactionRequestObject) (SynchronizeSubscriptionTransactionResponseObject, error)
	// AuthorizeMediaUpload Authorize a restricted temporary TOS upload
	// (POST /v1/media/upload-authorizations)
	AuthorizeMediaUpload(ctx context.Context, request AuthorizeMediaUploadRequestObject) (AuthorizeMediaUploadResponseObject, error)
	// RecordPrivacyConsents Record the current privacy consent versions
	// (POST /v1/privacy/consents)
	RecordPrivacyConsents(ctx context.Context, request RecordPrivacyConsentsRequestObject) (RecordPrivacyConsentsResponseObject, error)
	// DeletePrivacyData Delete all managed service data for the caller
	// (DELETE /v1/privacy/data)
	DeletePrivacyData(ctx context.Context, request DeletePrivacyDataRequestObject) (DeletePrivacyDataResponseObject, error)
	// GetManagedAIProduct Describe the managed-AI subscription product
	// (GET /v1/products/managed-ai)
	GetManagedAIProduct(ctx context.Context, request GetManagedAIProductRequestObject) (GetManagedAIProductResponseObject, error)
}

type StrictHandlerFunc func(ctx *gin.Context, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictGinServerOptions struct {
	// RequestErrorHandlerFunc is called when a request cannot be parsed or
	// decoded. It is invoked for JSON bind failures, form parse/bind errors,
	// multipart reader errors, media type parse errors, missing multipart
	// boundaries, and request body read errors. The default returns 400.
	RequestErrorHandlerFunc func(ctx *gin.Context, err error)
	// HandlerErrorFunc is called when the application handler (or any
	// middleware wrapping it) returns a non-nil error. The default returns 500.
	HandlerErrorFunc func(ctx *gin.Context, err error)
	// ResponseErrorHandlerFunc is called when the response object fails to
	// serialize (Visit*Response returns an error) or when the handler returns
	// an unexpected response type. The default returns 500.
	ResponseErrorHandlerFunc func(ctx *gin.Context, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictGinServerOptions{
		RequestErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		},
		HandlerErrorFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
		ResponseErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictGinServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		}
	}
	if options.HandlerErrorFunc == nil {
		options.HandlerErrorFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictGinServerOptions
}

// GetHealth operation middleware
func (sh *strictHandler) GetHealth(ctx *gin.Context) {
	var request GetHealthRequestObject

	handler := func(ctx *gin.Context, request interface{}) (interface{}, error) {
		return sh.ssi.GetHealth(ctx, request.(GetHealthRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "GetHealth")
	}

	response, err := handler(ctx, request)

	if err != nil {
		sh.options.HandlerErrorFunc(ctx, err)
	} else if validResponse, ok := response.(GetHealthResponseObject); ok {
		if err := validResponse.VisitGetHealthResponse(ctx.Writer); err != nil {
			sh.options.ResponseErrorHandlerFunc(ctx, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(ctx, fmt.Errorf("unexpected response type: %T", response))
	}
}

